import{Lt as e,Vt as t,_t as n,bt as r,mt as i,vt as a,yt as o}from"./chunks/framework.CsLlEPF4.js";import{n as s,t as c}from"./chunks/PluginFeedback.BpCHXCV1.js";var l=JSON.parse(`{"title":"Better BibTeX","description":"","frontmatter":{"plugin":"retorquere/zotero-better-bibtex"},"headers":[],"relativePath":"user-guide/plugins/better-bibtex.md","filePath":"wiki/user-guide/plugins/better-bibtex.md"}`),u=Object.assign({name:`user-guide/plugins/better-bibtex.md`},{setup(l){return(l,u)=>{let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),n(`div`,null,[u[0]||=i(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidepluginsbetter-bibtex.md for this page in Markdown format`,-1),u[1]||=i(`h1`,{id:`better-bibtex`,tabindex:`-1`},[o(`Better BibTeX `),i(`a`,{class:`header-anchor`,href:`#better-bibtex`,"aria-label":`Permalink to “Better BibTeX”`},`​`)],-1),r(s),u[2]||=a(`<div class="info custom-block"><p class="custom-block-title">关于插件</p><p>Better BibTeX (BBT) 插件可帮助管理参考文献数据，主要配合 <a href="https://latex-project.org" target="_blank" rel="noreferrer">LaTeX</a>、<a href="https://markdownguide.org" target="_blank" rel="noreferrer">Markdown</a> 等围绕文本文件的工具链。</p><ul><li>项目主页：<a href="https://retorque.re/zotero-better-bibtex/" target="_blank" rel="noreferrer">Better BibTeX for Zotero</a></li><li>插件下载地址 <ul><li><a href="https://github.com/retorquere/zotero-better-bibtex/releases" target="_blank" rel="noreferrer">GitHub Release</a></li><li><a href="/plugins/#search-better-bibtex-for-zotero">国内镜像</a></li></ul></li></ul></div><h2 id="title-case" tabindex="-1">导出<code>*.bib</code>时转换为标题大小写 <a class="header-anchor" href="#title-case" aria-label="Permalink to “导出*.bib时转换为标题大小写”">​</a></h2><p>关于文献题名的大小写，历来有句子（Sentence case）、标题（Title Case）两种习惯。</p><p>由于 CSL 与 Bib(La)TeX 生成参考文献著录列表的原理不同，一般推荐<a href="./../edit-items#标题的大小写">在 Zotero 中按「句子大小写」存储</a>，而在<code>*.bib</code>中按「标题大小写」存储。因此，从 Zotero 导出<code>*.bib</code>时，<a href="https://retorque.re/zotero-better-bibtex/support/faq/index.html#bbt-is-changing-the-capitalization-of-my-titles--why" target="_blank" rel="noreferrer">Better BibTeX 插件默认会将题名转换为标题大小写</a>。</p><p>国家推荐性标准 <a href="https://std.samr.gov.cn/gb/search/gbDetailed?id=71F772D8055ED3A7E05397BE0A0AB82A" target="_blank" rel="noreferrer">GB/T 7714《信息与文献 参考文献著录规则》</a>的示例常用句子大小写，但正文仅要求「著录西文文献时，大写字母的使用应符合信息资源本身文种的习惯用法」（2015 版国标 §6.6、2025 版国标 §5.6）。考虑到国标的示例仅为辅助理解而列出，并非需要遵守的条款（<a href="https://std.samr.gov.cn/gb/search/gbDetailed?id=A24AF19F41445C2EE05397BE0A0A5E0D" target="_blank" rel="noreferrer">GB/T 1.1</a>），我们通常不必过分关注大小写，而只要保留默认设置，让 Bib(La)TeX 自动处理，再确认全篇一致即可。</p><p>如果实在有特殊需要，可前往「Zotero 设置 → Better BibTeX → 杂项」，取消勾选<a href="https://retorque.re/zotero-better-bibtex/preferences/export/index.html#apply-title-casing-to-titles" target="_blank" rel="noreferrer">「对标题应用标题大小写格式」</a>。</p>`,6),r(c),r(d),r(f)])}}});export{l as __pageData,u as default};